-- =====================================================================
-- 006_notifications.sql
-- In-app notifications.
--
-- Notifications are generated by a trigger on audit_logs, so every
-- governance action that is audited automatically notifies the people it
-- concerns, in the same transaction (a rolled-back action notifies nobody).
--
-- Who is notified:
--   * release submitted          -> every active QA Lead and Release Manager
--   * approval / rejection       -> the release's stakeholders (creator,
--                                   submitter and everyone who signed it)
--   * fully approved             -> stakeholders + all Release Managers
--   * break-glass, deployment, outcome, edit-after-sign-off, expiry,
--     cancellation               -> stakeholders (+ RMs for break-glass)
--   * account requested          -> all Release Managers
--   * account approved / re-roled -> that user
-- The person who performed the action is never notified about it.
-- =====================================================================

CREATE TABLE notifications (
    id          BIGSERIAL PRIMARY KEY,
    user_id     INT  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind        TEXT NOT NULL,      -- review_requested, approved, rejected, signed, ...
    title       TEXT NOT NULL,
    message     TEXT NOT NULL,
    release_id  INT  REFERENCES releases(id) ON DELETE CASCADE,
    actor_id    INT  REFERENCES users(id),
    audit_seq   BIGINT,             -- the audit entry that caused it
    created_at  TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    read_at     TIMESTAMPTZ
);
CREATE INDEX idx_notifications_user ON notifications(user_id, id DESC);
CREATE INDEX idx_notifications_unread ON notifications(user_id) WHERE read_at IS NULL;

-- Active users holding a role.
CREATE FUNCTION role_members(p_role TEXT) RETURNS SETOF INT
LANGUAGE sql STABLE AS $$
    SELECT ur.user_id FROM user_roles ur JOIN users u ON u.id = ur.user_id
    WHERE ur.role_code = p_role AND u.status = 'ACTIVE';
$$;

-- Creator, submitter and everyone who ever signed the release.
CREATE FUNCTION release_stakeholders(p_release INT) RETURNS SETOF INT
LANGUAGE sql STABLE AS $$
    SELECT created_by FROM releases WHERE id = p_release
    UNION SELECT submitted_by FROM releases WHERE id = p_release AND submitted_by IS NOT NULL
    UNION SELECT user_id FROM approvals WHERE release_id = p_release;
$$;

CREATE FUNCTION notify_users(p_users INT[], p_kind TEXT, p_title TEXT, p_message TEXT,
                             p_release INT, p_actor INT, p_seq BIGINT)
RETURNS VOID LANGUAGE sql AS $$
    INSERT INTO notifications(user_id, kind, title, message, release_id, actor_id, audit_seq)
    SELECT DISTINCT u.id, p_kind, p_title, p_message, p_release, p_actor, p_seq
    FROM unnest(p_users) AS t(uid)
    JOIN users u ON u.id = t.uid AND u.status = 'ACTIVE'
    WHERE t.uid IS DISTINCT FROM p_actor;
$$;

CREATE FUNCTION notify_from_audit() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
    d        JSONB := NEW.details;
    r        releases%ROWTYPE;
    v_name   TEXT;
    v_actor  TEXT;
    v_stake  INT[];
    v_rms    INT[] := ARRAY(SELECT role_members('RELEASE_MANAGER'));
    v_qas    INT[] := ARRAY(SELECT role_members('QA_LEAD'));
    v_role   TEXT;
BEGIN
    SELECT coalesce(full_name, username) INTO v_actor FROM users WHERE id = NEW.actor_id;
    v_actor := coalesce(v_actor, 'The system');

    IF NEW.entity = 'release' THEN
        SELECT * INTO r FROM releases WHERE id = NEW.entity_id;
        IF NOT FOUND THEN RETURN NULL; END IF;           -- e.g. a deleted draft
        v_name  := r.app_name || ' ' || r.version || ' (' || r.ticket_id || ')';
        v_stake := ARRAY(SELECT release_stakeholders(r.id));
        v_role  := (SELECT name FROM roles WHERE code = d->>'role');

        CASE NEW.action
        WHEN 'RELEASE_SUBMITTED' THEN
            PERFORM notify_users(v_qas || v_rms, 'review_requested', 'Review requested',
                v_actor || ' submitted ' || v_name || ' for approval (' || lower(d->>'tier') || ' risk, '
                || round((d->>'probability')::numeric * 100) || '% failure risk).',
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'APPROVAL_APPROVE' THEN
            PERFORM notify_users(v_stake, 'signed', 'Sign-off received',
                v_actor || ' approved ' || v_name || ' as ' || coalesce(v_role, d->>'role') || '.',
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'APPROVAL_REJECT' THEN
            PERFORM notify_users(v_stake, 'rejected', 'Release rejected',
                v_actor || ' rejected ' || v_name || coalesce(': "' || (d->>'comment') || '"', '.'),
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'STATUS_CHANGED' THEN
            IF d->>'to' = 'APPROVED' THEN
                PERFORM notify_users(v_stake || v_rms, 'approved', 'Release approved',
                    v_name || ' has every required sign-off and is ready to deploy.',
                    r.id, NULL, NEW.seq);
            END IF;
        WHEN 'BREAK_GLASS_APPROVAL' THEN
            PERFORM notify_users(v_stake || v_rms, 'break_glass', 'Emergency approval',
                v_actor || ' used break-glass to approve ' || v_name || ': "' || (d->>'justification')
                || '". A post-incident review is now due.',
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'DEPLOYMENT_STARTED' THEN
            PERFORM notify_users(v_stake, 'deploying', 'Deployment started',
                v_actor || ' started deploying ' || v_name || '.', r.id, NEW.actor_id, NEW.seq);
        WHEN 'OUTCOME_RECORDED' THEN
            PERFORM notify_users(v_stake, CASE d->>'outcome' WHEN 'DEPLOYED' THEN 'deployed' ELSE 'failed' END,
                CASE d->>'outcome' WHEN 'DEPLOYED' THEN 'Deployed successfully'
                                   WHEN 'FAILED' THEN 'Deployment failed' ELSE 'Release rolled back' END,
                v_name || CASE d->>'outcome' WHEN 'DEPLOYED' THEN ' is live.'
                                            WHEN 'FAILED' THEN ' failed to deploy'
                                            ELSE ' was rolled back' END
                || CASE WHEN d->>'outcome' <> 'DEPLOYED' THEN coalesce(': ' || (d->>'notes'), '.') ELSE '' END,
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'RELEASE_REVISED' THEN
            IF d->>'status_before' IN ('IN_REVIEW', 'APPROVED') THEN
                PERFORM notify_users(v_stake, 'revised', 'Release changed after sign-off',
                    v_actor || ' edited ' || v_name || '. Earlier signatures were invalidated; it must be re-scored and re-approved.',
                    r.id, NEW.actor_id, NEW.seq);
            END IF;
        WHEN 'APPROVALS_EXPIRED' THEN
            PERFORM notify_users(v_stake, 'expired', 'Approvals expired',
                'Sign-offs for ' || v_name || ' expired before deployment. It is back in review.',
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'RELEASE_CANCELLED' THEN
            PERFORM notify_users(v_stake, 'cancelled', 'Release cancelled',
                v_actor || ' cancelled ' || v_name || coalesce(': ' || (d->>'reason'), '.'),
                r.id, NEW.actor_id, NEW.seq);
        WHEN 'INCIDENT_REVIEW_COMPLETED' THEN
            PERFORM notify_users(v_rms || v_stake, 'review_completed', 'Incident review completed',
                v_actor || ' completed the post-incident review for ' || v_name || '.',
                r.id, NEW.actor_id, NEW.seq);
        ELSE
            NULL;
        END CASE;

    ELSIF NEW.entity = 'user' THEN
        CASE NEW.action
        WHEN 'USER_REGISTERED' THEN
            PERFORM notify_users(v_rms, 'account_request', 'New account request',
                (d->>'username') || ' registered and requested the '
                || (SELECT name FROM roles WHERE code = d->>'requested_role') || ' role.',
                NULL, NEW.actor_id, NEW.seq);
        WHEN 'USER_APPROVED' THEN
            PERFORM notify_users(ARRAY[NEW.entity_id], 'account_approved', 'Welcome aboard',
                'Your account was approved as ' || (SELECT name FROM roles WHERE code = d->>'granted_role') || '.',
                NULL, NEW.actor_id, NEW.seq);
        WHEN 'USER_ROLE_CHANGED' THEN
            PERFORM notify_users(ARRAY[NEW.entity_id], 'role_changed', 'Your role changed',
                v_actor || ' changed your role to ' || (SELECT name FROM roles WHERE code = d->>'to') || '.',
                NULL, NEW.actor_id, NEW.seq);
        ELSE
            NULL;
        END CASE;
    END IF;
    RETURN NULL;
END $$;

CREATE TRIGGER trg_audit_notify AFTER INSERT ON audit_logs
    FOR EACH ROW EXECUTE FUNCTION notify_from_audit();

-- Reading is filtered by user in the API; marking as read is done through
-- functions that only touch the caller's own notifications.
CREATE FUNCTION mark_notification_read(p_id BIGINT, p_user INT) RETURNS BOOLEAN
LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
    WITH u AS (UPDATE notifications SET read_at = now()
               WHERE id = p_id AND user_id = p_user AND read_at IS NULL RETURNING 1)
    SELECT EXISTS (SELECT 1 FROM u);
$$;

CREATE FUNCTION mark_all_notifications_read(p_user INT) RETURNS INT
LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
    WITH u AS (UPDATE notifications SET read_at = now()
               WHERE user_id = p_user AND read_at IS NULL RETURNING 1)
    SELECT count(*)::int FROM u;
$$;

REVOKE EXECUTE ON FUNCTION role_members(TEXT), release_stakeholders(INT),
    notify_users(INT[], TEXT, TEXT, TEXT, INT, INT, BIGINT), notify_from_audit(),
    mark_notification_read(BIGINT, INT), mark_all_notifications_read(INT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mark_notification_read(BIGINT, INT), mark_all_notifications_read(INT) TO release_app;
GRANT SELECT ON notifications TO release_app;
